defaults.init-script:
(() => {
  if (!location.pathname.startsWith("/app/profile/onboarding")) return;
  try { Object.keys(localStorage).filter(k => k.startsWith("orbit.onboarding")).forEach(k => localStorage.removeItem(k)); sessionStorage.clear(); } catch {}
  const real = window.fetch.bind(window);
  const ok = (data) => Promise.resolve(new Response(JSON.stringify({ success: true, data }), { status: 200, headers: { "content-type": "application/json" } }));
  let rev = 0, flow = null, updated = 0, mutationId;
  let profile = { displayName: "", organization: "", role: "", headline: "", bio: "", relationshipGoal: "", handles: {}, offering: [], seeking: [], topics: [], updatedAt: "2026-11-25T00:00:00.000Z" };
  const payload = () => ({ state: "success", profile, mutationId, onboarding: { policyVersion: 2, status: profile.displayName && profile.secondaryIndustryId ? "complete" : "incomplete", missingFields: [] } });
  window.fetch = (input, init = {}) => {
    const url = String(input && input.url ? input.url : input);
    const body = () => JSON.parse(String(init.body || "{}"));
    if (url.includes("/api/profile/onboarding-progress")) {
      if ((init.method || "GET") === "POST") { const c = body(); rev += 1;
        if (c.action === "initialize") flow = flow || { version: 1, lastConfirmedScreen: 0, currentScreen: 1, deferred: false, finishedAt: null };
        if (c.action === "confirm") flow = { ...flow, lastConfirmedScreen: c.screen, currentScreen: c.screen >= 5 ? null : c.screen + 1 };
        flow = { ...flow, revision: "r" + rev }; }
      return ok(flow);
    }
    if (url.includes("/api/profile/autofill-inference")) return ok({ status: "ready", primaryIndustryId: null, secondaryIndustryId: null, seniorityLevel: "c_level", offering: ["資本政策の知見", "SaaS の営業組織づくり", "エンジニア採用"], topics: ["SaaS", "製造業 DX", "組織づくり"] });
    if (url.includes("/api/profile/seek-suggestions")) return ok({ suggestions: ["企業の意思決定者"] });
    if (url.includes("/api/profile/intro-draft")) return ok({ headline: "業務 SaaS の代表", bio: "株式会社ミナトリンク代表の佐藤です。製造業向けの業務 SaaS を展開しています。シリーズAの資金調達と新規顧客開拓に力を入れています。", model: "fixture", provider: "fixture" });
    if (url.includes("/api/contact-drafts/business-card/scan")) return ok({ draft: { displayName: "佐藤 健一", organization: "株式会社ミナトリンク", role: "代表取締役 CEO", email: "sato@minatolink.example", phone: "03-5555-0142" }, ocr: { structuredExtraction: { primaryIndustryId: "finance_investment", secondaryIndustryId: "finance_investment.insurance", seniorityLevel: "c_level", regionCountryCode: "JP", regionCity: "Tokyo" } } });
    if (/\/api\/profile(\?|$)/.test(url)) {
      if (init.method === "PUT") { const { expectedUpdatedAt, mutationId: id, ...f } = body(); mutationId = id; updated += 1; profile = { ...profile, ...f, updatedAt: "2026-11-25T00:00:0" + updated + ".000Z" }; }
      return ok(payload());
    }
    return real(input, init);
  };
})();
